"""spud: the one program that writes the ledger (SPD-007, ledger CLI v1).

Run it as  python3.14 -I -S bin/spud [--as ACTOR] [--json] <command> ...

bin/spud is the launcher and this module is the program (SPD-016): Python compiles a script on every run, and
compiling this one took a hook run 25 of its 65 ms, so the launcher loads the program as a module with its
bytecode cached.  Running this file directly refuses.

The ledger is one SQLite file, <SPUD_HOME>/.spud/ledger.db, in WAL mode.
Markdown under ledger/ and reports/ is what `spud render` generates from it;
`spud import` reads the markdown-v0 files once.  Design: the ledger database
spike (docs/spikes/2026-09-12-ledger-database.md, SPD-006) as amended by the
decisions recorded on SPD-007.  Python 3.14 standard library only.

Exit codes: 0 ok, 1 error, 2 usage, 3 ownership refused, 4 limit refused,
5 state transition refused, 6 render conflict (a hand-edited file).
"""

import bisect
import contextlib
import fcntl
import functools
import json
import os
import re
import shlex
import sqlite3
import sys
import time
from datetime import datetime
from pathlib import Path


class LazyModule:
    """A standard-library module imported at its first attribute access.  No hook uses these, and importing them up
    front cost every hook run about 11 ms (SPD-016)."""

    def __init__(self, name):
        self._name = name

    def __getattr__(self, attr):
        module = __import__(self._name)
        globals()[self._name] = module  # from now on the name is the module itself
        return getattr(module, attr)


argparse = LazyModule("argparse")
fractions = LazyModule("fractions")
hashlib = LazyModule("hashlib")
subprocess = LazyModule("subprocess")
tempfile = LazyModule("tempfile")

