def normalize_argv(argv):
    """`--as ACTOR`, `--as=ACTOR` and `--json` are accepted anywhere on the line (a subagent
    types `spud member result --as <id> ...` as naturally as the other order); they are
    hoisted in front of the command for argparse.  Tokens after a literal `--` stay put."""
    front, rest = [], []
    i = 0
    while i < len(argv):
        tok = argv[i]
        if tok == "--":
            rest.extend(argv[i:])
            break
        if tok == "--as" and i + 1 < len(argv):
            front += ["--as", argv[i + 1]]
            i += 2
            continue
        if tok.startswith("--as=") or tok == "--json":
            front.append(tok)
            i += 1
            continue
        rest.append(tok)
        i += 1
    return front + rest


class HookCall:
    """What the parser gives for exactly `spud hook <event>`, the line settings sync installs: a hook run skips building
    the parser, which any other line still goes through (SPD-016)."""

    command = "hook"
    actor = None
    json = False

    def __init__(self, event, project=None):
        self.event = event
        self.project = project
        self.func = cmd_hook


def main(argv=None):
    for stream in (sys.stdout, sys.stderr):
        with contextlib.suppress(Exception):
            stream.reconfigure(encoding="utf-8", errors="replace")
    argv = sys.argv[1:] if argv is None else list(argv)
    if len(argv) == 2 and argv[0] == "hook" and argv[1] in HOOK_EVENTS:
        args = HookCall(argv[1])
    elif len(argv) == 4 and argv[0] == "hook" and argv[1] in HOOK_EVENTS and argv[2] == "--project":  # a project's hook line (SPD-014)
        args = HookCall(argv[1], argv[3])
    else:
        args = build_parser().parse_args(normalize_argv(argv))
    ctx = None
    try:
        home, how = resolve_home(os.environ, Path(__file__))
        ctx = Ctx(home, how, args.json)
        ACTIVE_CTX[:] = [ctx]
        result = args.func(ctx, args)
    except SpudError as e:
        sys.stderr.write("spud: %s\n" % e.message)
        if args.json:
            payload = {"ok": False, "error": e.message, "exit": e.code}
            payload.update(e.data)
            sys.stdout.write(json.dumps(payload, indent=2) + "\n")
        return e.code
    except sqlite3.Error as e:
        sys.stderr.write("spud: database error: %s\n" % e)
        if args.json:
            sys.stdout.write(json.dumps({"ok": False, "error": "database error: %s" % e, "exit": EXIT_ERROR}, indent=2) + "\n")
        return EXIT_ERROR
    if result.raw is not None:
        if result.raw:
            sys.stdout.write(result.raw.rstrip("\n") + "\n")
        if result.stderr:
            sys.stderr.write(result.stderr.rstrip("\n") + "\n")
        return result.exit_code
    if args.json:
        payload = {"ok": result.exit_code == EXIT_OK}
        if result.exit_code != EXIT_OK:
            payload.update({"error": result.stderr, "exit": result.exit_code})
        payload.update(result.data)
        sys.stdout.write(json.dumps(payload, indent=2) + "\n")
    elif result.text:
        sys.stdout.write(result.text.rstrip("\n") + "\n")
    if result.stderr:
        # a command that did its work and still exits non-zero (member resum leaving a sum) says why
        sys.stderr.write("spud: %s\n" % result.stderr.rstrip("\n"))
    # A recording hook that failed open left its gap in the spool; any successful command drains it.
    if args.command != "hook" and result.exit_code == EXIT_OK:
        with contextlib.suppress(Exception):
            spool_drain(ctx)
    return result.exit_code


if __name__ == "__main__":
    sys.stderr.write("spud: run the launcher, bin/spud, not %s: the hooks and the allow rules know the launcher\n" % os.path.basename(__file__))
    sys.exit(EXIT_USAGE)
